/* Mestrado em Epidemiologia (IMS/UERJ): practice for the written selection exam.
 *
 * Content lives in app/mestrado/data.js (window.MESTRADO), generated by
 * scripts/build_mestrado.py: past exams (2023-2025, unofficial answer key) plus questions
 * written from the textbook (Medronho et al., Epidemiologia, caps 1-6, 8 and 18). Every
 * statement points to the book page and to a chapter summary.
 *
 * Exam format: 3 hours, 8 closed questions (5 true/false statements each, 1 point) and
 * 1 open question (2 points). Pace: 180 min / 10 points = 18 min per point.
 *
 * The shell (app/app.js) owns routing, the top bar and sync; this module renders the
 * #/mestrado/... screens and keeps progress in state.mestrado (synced with the account). */
(function () {
  const DATA = window.MESTRADO || { caps: {}, sections: [], questions: [], pdfs: [] };
  const QS = DATA.questions;
  const qById = Object.fromEntries(QS.map((q) => [q.id, q]));
  const itemById = {}, itemQ = {};
  QS.forEach((q) => (q.items || []).forEach((it) => { itemById[it.id] = it; itemQ[it.id] = q; }));
  const ITEMS = Object.values(itemById);
  const secById = Object.fromEntries(DATA.sections.map((s) => [s.id, s]));
  const CAPS = DATA.caps;
  const CAP_NUMS = Object.keys(CAPS).map(Number).sort((a, b) => a - b);
  const YEARS = [...new Set(QS.filter((q) => q.prova).map((q) => q.prova))].sort();
  const EXAM_MIN = 180, EXAM_POINTS = 10;
  const PER_POINT = (EXAM_MIN * 60) / EXAM_POINTS; // 18 min per point
  const RUN_KEY = "mestrado:run", LAST_KEY = "mestrado:last";
  const DESIGN = ["Experimental", "Coorte", "Caso-controle", "Transversal", "Ecológico", "Nenhum"];

  let sh = null;
  const st = () => sh.getState();
  const esc = (s) => sh.esc(s);

  /* ---------------- helpers ---------------- */
  const mmss = (s) => { s = Math.max(0, Math.round(s)); const h = Math.floor(s / 3600), m = Math.floor((s % 3600) / 60); return h ? `${h}h${String(m).padStart(2, "0")}` : `${m}:${String(s % 60).padStart(2, "0")}`; };
  const pct = (a, b) => (b ? Math.round((100 * a) / b) : 0);
  const fmt = (x) => (Math.round(x * 10) / 10).toLocaleString("pt-BR");
  const shuffle = (xs) => { const a = xs.slice(); for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; } return a; };
  const uid = () => Date.now().toString(36) + Math.random().toString(36).slice(2, 7);
  const load = (k) => { try { return JSON.parse(localStorage.getItem(k) || "null"); } catch { return null; } };
  const store = (k, v) => { try { v == null ? localStorage.removeItem(k) : localStorage.setItem(k, JSON.stringify(v)); } catch { /* ignore */ } };
  const capName = (c) => (CAPS[c] ? `Cap. ${c} · ${CAPS[c].title}` : `Cap. ${c}`);
  const pts = (q) => (q.type === "open" ? q.pts || 2 : 1);
  const isDesign = (q) => q.type === "choice" && q.opts && q.opts[0] === "Estudo experimental";
  const optLabel = (q, k) => (isDesign(q) ? DESIGN[k] : q.opts[k]);
  const ansLabel = (q, it) => (q.type === "choice" ? optLabel(q, it.a) : it.a === "V" ? "Verdadeira" : "Falsa");
  const srcLabel = (q) => (q.prova ? `UERJ ${q.prova} · Questão ${q.num}` : "Questão do livro");
  const pageLabel = (r) => `p. ${r.p}${r.p2 !== r.p ? `-${r.p2}` : ""}`;
  const imgSrc = (f) => `app/mestrado/img/${encodeURIComponent(f)}`;

  function record(id, ok) {
    const s = st();
    const r = s.q[id] || { r: 0, w: 0 };
    s.q[id] = { r: (r.r || 0) + (ok ? 1 : 0), w: (r.w || 0) + (ok ? 0 : 1), last: ok ? 1 : 0, at: Date.now() };
    if (!s.days.includes(sh.today())) s.days.push(sh.today());
  }
  const recordOpen = (qid, score) => { st().q[`open:${qid}`] = { score, max: pts(qById[qid]), at: Date.now() }; };
  const wrongItems = () => ITEMS.filter((it) => st().q[it.id] && st().q[it.id].last === 0);
  const seenItems = () => ITEMS.filter((it) => st().q[it.id]);

  /* ---------------- choosing questions ---------------- */
  function itemWeight(id) {
    const r = st().q[id];
    if (!r) return 3;
    if (r.last === 0) return 6;
    return Math.max(0.15, 1 / (1 + (r.r || 0)));
  }
  function qWeight(q) {
    if (q.type === "open") { const r = st().q[`open:${q.id}`]; return r ? Math.max(0.3, 1 - r.score / r.max) + 0.2 : 2; }
    return q.items.reduce((s, it) => s + itemWeight(it.id), 0) / q.items.length;
  }
  function weightedPick(qs, n) {
    const pool = qs.map((q) => ({ id: q.id, w: qWeight(q) }));
    const out = [];
    while (out.length < n && pool.length) {
      const total = pool.reduce((s, p) => s + p.w, 0);
      let x = Math.random() * total, i = 0;
      while (i < pool.length - 1 && (x -= pool[i].w) > 0) i++;
      out.push(pool.splice(i, 1)[0].id);
    }
    return out;
  }
  // a random exam shaped like the real one: 8 closed questions spread over the chapters the
  // exams usually cover, then one open question
  const SLOTS = [["design"], [2], [2, 18], [3], [3], [4], [5], [6, 1]];
  function randomExam() {
    const closed = QS.filter((q) => q.type === "vf" && q.items.length >= 5);
    const picked = [];
    for (const slot of SLOTS) {
      const pool = slot[0] === "design" ? QS.filter((q) => isDesign(q) && !picked.includes(q.id))
        : closed.filter((q) => slot.includes(q.cap) && !picked.includes(q.id));
      picked.push(...weightedPick(pool, 1));
    }
    picked.push(...weightedPick(QS.filter((q) => q.type === "open"), 1));
    return picked;
  }

  /* ---------------- book references and the PDFs on this device ---------------- */
  // The textbook PDFs are never uploaded: the student can keep them in this browser
  // (IndexedDB) so a reference can open the PDF at the right page.
  const DB_NAME = "mestrado-pdfs";
  let pdfKeys = new Set();
  function idb() {
    return new Promise((res, rej) => {
      const r = indexedDB.open(DB_NAME, 1);
      r.onupgradeneeded = () => r.result.createObjectStore("pdf");
      r.onsuccess = () => res(r.result);
      r.onerror = () => rej(r.error);
    });
  }
  async function pdfOp(mode, fn) {
    const db = await idb();
    return new Promise((res, rej) => {
      const tx = db.transaction("pdf", mode);
      const out = fn(tx.objectStore("pdf"));
      tx.oncomplete = () => res(out && "result" in out ? out.result : undefined);
      tx.onerror = () => rej(tx.error);
    });
  }
  async function refreshPdfKeys() {
    try { pdfKeys = new Set(await pdfOp("readonly", (s) => s.getAllKeys())); } catch { pdfKeys = new Set(); }
  }
  const pdfFor = (page) => DATA.pdfs.find((p) => page >= p.from && page <= p.to);
  function pdfKeyFromName(name) {
    const n = name.replace(/\s+/g, "");
    const m = n.match(/Cap(?:itulo)?_?(3)_?Pt_?([12])/i) || n.match(/Cap(?:itulo)?_?(8)e18/i) || n.match(/Cap(?:itulo)?_?(\d+)/i);
    if (!m) return null;
    if (/8e18/i.test(m[0])) return "Cap8e18";
    if (m[2]) return `Cap3_Pt${m[2]}`;
    return `Cap${m[1]}`;
  }
  async function openPdf(page) {
    const p = pdfFor(page);
    if (!p || !pdfKeys.has(p.key)) { location.hash = "#/mestrado/livro"; sh.toast("Carregue os PDFs do livro nesta tela"); return; }
    const w = window.open("", "_blank"); // open synchronously so pop-up blockers allow it
    try {
      const blob = await pdfOp("readonly", (s) => s.get(p.key));
      const url = URL.createObjectURL(new Blob([blob], { type: "application/pdf" })) + `#page=${page - p.offset}`;
      if (w) w.location.href = url; else location.href = url;
    } catch { if (w) w.close(); sh.toast("Não consegui abrir o PDF"); }
  }
  function refsHtml(refs) {
    return `<div class="ms-refs">${refs.map((r) => {
      const s = secById[r.s];
      const p = pdfFor(r.p);
      return `<span class="ms-ref"><a href="#/mestrado/livro/${r.c}/${r.s}">📖 Cap. ${r.c}, ${pageLabel(r)}${s ? ` · ${esc(s.title)}` : ""}</a>${p && pdfKeys.has(p.key) ? `<button class="ms-pdf" data-pdf="${r.p}" title="Abrir o PDF do livro nesta página">PDF ↗</button>` : ""}</span>`;
    }).join("")}</div>`;
  }
  function wirePdfButtons(root) {
    (root || document).querySelectorAll("[data-pdf]").forEach((b) => b.addEventListener("click", (e) => { e.preventDefault(); openPdf(+b.dataset.pdf); }));
  }

  /* ---------------- rendering a question ---------------- */
  function contextHtml(q) {
    return `${(q.ctx || []).map((p) => `<p class="ms-ctx">${esc(p)}</p>`).join("")}
      ${(q.imgs || []).map((im) => `<figure class="ms-fig"><a href="${imgSrc(im.f)}" target="_blank" rel="noopener"><img src="${imgSrc(im.f)}" alt="${esc(im.cap)}" loading="lazy"></a><figcaption>${esc(im.cap)}</figcaption></figure>`).join("")}
      ${q.table ? `<div class="ms-table"><table><thead><tr>${q.table[0].map((h) => `<th>${esc(h)}</th>`).join("")}</tr></thead><tbody>${q.table.slice(1).map((r) => `<tr>${r.map((c) => `<td>${esc(c)}</td>`).join("")}</tr>`).join("")}</tbody></table></div>` : ""}`;
  }
  function feedbackHtml(q, it, given) {
    const ok = given === it.a;
    return `<div class="ms-fb ${ok ? "ok" : "bad"}"><b>${ok ? "✓ Certo" : given == null ? "– Em branco" : "✗ Errado"}</b> · Gabarito${q.prova ? " (não oficial)" : ""}: <b>${esc(ansLabel(q, it))}</b>
      ${it.disc ? `<span class="pill warn" title="Assertiva ambígua: o gabarito pode ser discutido">discutível</span>` : ""}
      <p>${esc(it.e)}</p>${refsHtml(it.refs)}</div>`;
  }
  // one gradable statement: V/F buttons, or option chips for choice questions
  function itemHtml(q, it, k, given, reveal) {
    const ok = given === it.a;
    const cls = reveal ? (ok ? "ok" : "bad") : "";
    const btns = q.type === "choice"
      ? `<div class="ms-opts ${isDesign(q) ? "design" : ""}">${q.opts.map((_, o) => {
          let c = given === o ? "on" : "";
          if (reveal) c = o === it.a ? "right" : given === o ? "wrong" : "";
          return `<button class="${c}" data-it="${it.id}" data-v="${o}" ${reveal ? "disabled" : ""}>${isDesign(q) ? `${o + 1}. ` : ""}${esc(optLabel(q, o))}</button>`;
        }).join("")}</div>`
      : `<div class="ms-vf">${["V", "F"].map((v) => {
          let c = given === v ? "on" : "";
          if (reveal) c = v === it.a ? "right" : given === v ? "wrong" : "";
          return `<button class="${c}" data-it="${it.id}" data-v="${v}" ${reveal ? "disabled" : ""} aria-label="${v === "V" ? "Verdadeira" : "Falsa"}">${v}</button>`;
        }).join("")}</div>`;
    const long = q.type === "choice" && it.t.length > 420;
    const text = long ? `<details class="ms-abs"><summary>${esc(it.t.slice(0, 260))}… <span class="muted">(ler resumo completo)</span></summary><p>${esc(it.t)}</p></details>` : `<p class="ms-st">${esc(it.t)}</p>`;
    return `<li class="ms-item ${cls} ${q.type}" id="it-${it.id.replace(/\W/g, "_")}"><div class="ms-row"><span class="ms-n">${q.type === "choice" ? String.fromCharCode(97 + k) + ")" : `${k + 1}.`}</span><div class="ms-body">${text}</div>${q.type === "vf" ? btns : ""}</div>
      ${q.type === "choice" ? btns : ""}${reveal ? feedbackHtml(q, it, given) : ""}</li>`;
  }
  function openHtml(q, o, reveal, gradable) {
    return `<div class="ms-open">
      <label class="dt-label" for="msText">Sua resposta (rascunho, fica só neste aparelho)</label>
      <textarea id="msText" rows="9" placeholder="Escreva sua resposta como faria na prova…">${esc(o.text || "")}</textarea>
      ${reveal ? `<div class="ms-key"><h3>Pontos que uma boa resposta aborda</h3><ul>${q.keys.map((k) => `<li>${esc(k)}</li>`).join("")}</ul>${q.ans ? `<p class="muted">${esc(q.ans)}</p>` : ""}${q.refs ? refsHtml(q.refs) : ""}</div>` : ""}
      ${reveal && gradable ? `<div class="ms-grade"><span class="dt-label">Autoavaliação (0 a ${fmt(pts(q))})</span><div class="goal-select">${scoreSteps(q).map((v) => `<button data-score="${v}" class="${o.score === v ? "on" : ""}">${fmt(v)}</button>`).join("")}</div></div>` : ""}
    </div>`;
  }
  const scoreSteps = (q) => { const out = []; for (let v = 0; v <= pts(q) + 1e-9; v += 0.5) out.push(v); return out; };

  // points earned on one question of a run
  function qScore(q, run) {
    if (q.type === "open") { const o = run.open[q.id]; return o && o.score != null ? o.score : 0; }
    const right = q.items.filter((it) => run.answers[it.id] === it.a).length;
    return (right / q.items.length) * pts(q);
  }

  /* ---------------- runs ---------------- */
  function startRun({ qids, title, mode, feedback }) {
    if (!qids.length) { sh.toast("Nenhuma questão para esse filtro"); return; }
    const total = qids.reduce((s, id) => s + pts(qById[id]), 0);
    const run = { id: uid(), qids, title, mode, feedback, answers: {}, open: {}, checked: {}, i: 0, start: Date.now(), limit: Math.round(total * PER_POINT) };
    store(RUN_KEY, run);
    location.hash = "#/mestrado/quiz";
  }
  function finishRun(run) {
    const end = Date.now();
    run.qids.forEach((id) => {
      const q = qById[id];
      if (q.type === "open") return;
      // blank statements count as zero in the score but don't go to the error list
      if (!run.checked[id]) q.items.forEach((it) => { if (run.answers[it.id] != null) record(it.id, run.answers[it.id] === it.a); });
    });
    const max = run.qids.reduce((s, id) => s + pts(qById[id]), 0);
    const score = run.qids.reduce((s, id) => s + qScore(qById[id], run), 0);
    const session = { id: run.id, at: end, mode: run.mode, title: run.title, n: run.qids.length, max, score: Math.round(score * 100) / 100, secs: Math.round((end - run.start) / 1000), limit: run.limit };
    st().sessions.unshift(session);
    st().sessions = st().sessions.slice(0, 200);
    if (!st().days.includes(sh.today())) st().days.push(sh.today());
    sh.save();
    store(LAST_KEY, { ...session, qids: run.qids, answers: run.answers, open: run.open });
    store(RUN_KEY, null);
    location.hash = "#/mestrado/resultado";
  }

  /* ---------------- screens ---------------- */
  function chapterStats(c) {
    const its = ITEMS.filter((it) => itemQ[it.id].cap === c);
    const seen = its.filter((it) => st().q[it.id]);
    const right = seen.filter((it) => st().q[it.id].last === 1);
    return { n: its.length, seen: seen.length, right: right.length };
  }
  function home() {
    sh.setNav("ms-home");
    const s = st();
    const seen = seenItems();
    const right = seen.filter((it) => s.q[it.id].last === 1).length;
    const wrong = wrongItems().length;
    const running = load(RUN_KEY);
    const streak = (() => { const set = new Set(s.days); let d = sh.today(); if (!set.has(d)) d = sh.addDays(d, -1); let n = 0; while (set.has(d)) { n++; d = sh.addDays(d, -1); } return n; })();
    const exams = QS.filter((q) => q.prova).length, opens = QS.filter((q) => q.type === "open").length;

    sh.view.innerHTML = `
      <div class="hello"><div><p class="muted" style="margin:0">Seleção de Mestrado · IMS/UERJ</p><h1>Epidemiologia 📊</h1></div></div>
      <div class="stack">
        ${running ? `<section class="card dt-resume"><div class="row"><span style="flex:1"><b>Em andamento:</b> ${esc(running.title)} · questão ${running.i + 1}/${running.qids.length}</span>
          <a class="btn primary" href="#/mestrado/quiz">Continuar</a><button class="btn ghost" id="msDiscard">Descartar</button></div></section>` : ""}

        <section class="card today ms-hero">
          <span class="pill">📝 Simulado completo</span>
          <h2>8 questões V/F + 1 aberta · 3 horas</h2>
          <p>No formato da prova: cada questão fechada vale 1 ponto (5 assertivas) e a aberta vale 2. A correção aparece no fim.</p>
          <div class="row">
            <button class="btn primary" id="msExam">Simulado aleatório</button>
            <label class="dt-select">ou prova de
              <select id="msYear">${YEARS.map((y) => `<option value="${y}">${y}</option>`).join("")}</select>
              <button class="btn ghost" id="msYearGo">Fazer</button></label>
          </div>
        </section>

        <section class="card">
          <h3 style="margin:0 0 4px">⚡ Treino rápido</h3>
          <p class="muted" style="margin:0 0 12px">Sem 3 horas livres? Faça algumas questões. O cronômetro usa o ritmo da prova: ${mmss(PER_POINT)} por questão fechada e ${mmss(2 * PER_POINT)} pela aberta.</p>
          <div class="dt-opts">
            <div><span class="dt-label">Questões</span><div class="goal-select" id="msN">${[1, 2, 3, 5].map((n) => `<button data-n="${n}" class="${n === 2 ? "on" : ""}">${n}</button>`).join("")}</div></div>
            <div><span class="dt-label">Foco</span>
              <select id="msFocus" class="dt-input">
                <option value="mix">Mistura inteligente (erradas e novas primeiro)</option>
                <option value="erros" ${wrong ? "" : "disabled"}>Questões com assertivas que errei (${wrong})</option>
                <option value="provas">Só provas anteriores (${exams})</option>
                <option value="design">Identificar desenhos de estudo</option>
                <option value="open">Questões abertas (${opens})</option>
                ${CAP_NUMS.map((c) => `<option value="c:${c}">${esc(capName(c))} (${QS.filter((q) => q.cap === c).length})</option>`).join("")}
              </select></div>
            <label class="dt-check"><input type="checkbox" id="msFeedback" checked> Corrigir cada questão logo após responder</label>
          </div>
          <div class="row" style="margin-top:12px"><button class="btn primary" id="msBite">Começar treino</button><span class="muted" id="msBudget" style="font-size:.9rem"></span></div>
        </section>

        <div class="stats">
          <div class="stat"><b>${seen.length}<small class="muted" style="font-size:.9rem">/${ITEMS.length}</small></b><span>assertivas vistas</span></div>
          <div class="stat"><b>${seen.length ? pct(right, seen.length) + "%" : "–"}</b><span>acerto (última resposta)</span></div>
          <div class="stat"><b>${streak} 🔥</b><span>dias seguidos</span></div>
        </div>

        <section class="card">
          <div class="row" style="justify-content:space-between;margin-bottom:10px"><h3 style="margin:0">Por capítulo</h3><a href="#/mestrado/livro">Resumos do livro →</a></div>
          <div class="dt-topics">${CAP_NUMS.map((c) => {
            const x = chapterStats(c);
            return `<button class="dt-topic" data-cap="${c}"><b>${esc(capName(c))}</b>
              <span class="bar" title="vistas"><i style="width:${pct(x.seen, x.n)}%;background:var(--accent)"></i></span>
              <small class="muted">${x.seen}/${x.n} assertivas · ${x.seen ? pct(x.right, x.seen) + "% de acerto" : "ainda não treinado"}</small></button>`;
          }).join("")}</div>
        </section>

        ${s.sessions.length ? `<section class="card"><h3 style="margin:0 0 8px">Últimos treinos</h3><ul class="dt-sessions">${s.sessions.slice(0, 8).map((x) => {
          const inTime = x.secs <= x.limit;
          return `<li><span class="t"><b>${esc(x.title)}</b><small class="muted">${new Date(x.at).toLocaleDateString("pt-BR", { day: "2-digit", month: "short" })} · ${mmss(x.secs)} de ${mmss(x.limit)}</small></span>
            <span class="pill ${pct(x.score, x.max) >= 70 ? "good" : ""}">${fmt(x.score)}/${fmt(x.max)}</span><span class="pill ${inTime ? "good" : "warn"}">${inTime ? "⏱ no tempo" : "⏱ acima"}</span></li>`;
        }).join("")}</ul></section>` : ""}

        <section class="card ms-note">
          <h3 style="margin:0 0 6px">Sobre as questões</h3>
          <p class="muted" style="margin:0">${QS.length} questões (${ITEMS.length} assertivas): as provas de ${YEARS.join(", ")} e questões escritas a partir dos capítulos 1-6, 8 e 18 do livro. Cada assertiva traz a explicação e a página do livro. <b>O gabarito das provas não é oficial</b> (a UERJ não o publicou); assertivas ambíguas estão marcadas como “discutível”.</p>
        </section>
        ${sh.syncCard()}
      </div>`;
    sh.renderSyncCard();

    let n = 2;
    const budget = () => { const b = document.getElementById("msBudget"); if (b) b.textContent = `Tempo equivalente na prova: ~${mmss(n * PER_POINT)}`; };
    budget();
    document.querySelectorAll("#msN [data-n]").forEach((b) => b.addEventListener("click", () => {
      n = +b.dataset.n; document.querySelectorAll("#msN [data-n]").forEach((x) => x.classList.toggle("on", x === b)); budget();
    }));
    document.getElementById("msExam").addEventListener("click", () => startRun({ qids: randomExam(), title: "Simulado aleatório", mode: "sim", feedback: false }));
    document.getElementById("msYearGo").addEventListener("click", () => {
      const y = +document.getElementById("msYear").value;
      startRun({ qids: QS.filter((q) => q.prova === y).sort((a, b) => a.num - b.num).map((q) => q.id), title: `Prova UERJ ${y}`, mode: `prova:${y}`, feedback: false });
    });
    document.getElementById("msBite").addEventListener("click", () => {
      const f = document.getElementById("msFocus").value;
      let pool, title;
      if (f === "erros") { const ids = new Set(wrongItems().map((it) => itemQ[it.id].id)); pool = QS.filter((q) => ids.has(q.id)); title = "Treino: assertivas erradas"; }
      else if (f === "provas") { pool = QS.filter((q) => q.prova && q.type !== "open"); title = "Treino: provas anteriores"; }
      else if (f === "design") { pool = QS.filter(isDesign); title = "Treino: desenhos de estudo"; }
      else if (f === "open") { pool = QS.filter((q) => q.type === "open"); title = "Treino: questões abertas"; }
      else if (f.startsWith("c:")) { const c = +f.slice(2); pool = QS.filter((q) => q.cap === c && q.type !== "open"); title = `Treino: ${capName(c)}`; }
      else { pool = QS.filter((q) => q.type !== "open"); title = n === 1 ? "Treino de 1 questão" : `Treino de ${n} questões`; }
      startRun({ qids: weightedPick(pool, n), title, mode: "bite", feedback: document.getElementById("msFeedback").checked });
    });
    document.querySelectorAll("[data-cap]").forEach((b) => b.addEventListener("click", () => {
      document.getElementById("msFocus").value = `c:${b.dataset.cap}`;
      document.getElementById("msBite").scrollIntoView({ behavior: "smooth", block: "center" });
    }));
    const discard = document.getElementById("msDiscard");
    if (discard) discard.addEventListener("click", () => { if (confirm("Descartar o treino em andamento?")) { store(RUN_KEY, null); home(); } });
  }

  let tick = null;
  function quiz() {
    sh.setNav("ms-home");
    const run = load(RUN_KEY);
    if (!run) { location.replace("#/mestrado"); return; }
    const n = run.qids.length;
    const saveRun = () => store(RUN_KEY, run);
    const answeredQ = (q) => (q.type === "open" ? !!(run.open[q.id] && run.open[q.id].text && run.open[q.id].text.trim()) : q.items.every((it) => run.answers[it.id] != null));

    function render() {
      clearInterval(tick);
      const q = qById[run.qids[run.i]];
      const checked = !!run.checked[q.id];
      const isLast = run.i === n - 1;
      const o = run.open[q.id] || (run.open[q.id] = {});
      const missing = q.type === "open" ? 0 : q.items.filter((it) => run.answers[it.id] == null).length;
      let action;
      if (run.feedback && !checked) action = `<button class="btn primary" id="msCheck">${q.type === "open" ? "Ver resposta-modelo" : missing ? `Corrigir (${missing} em branco)` : "Corrigir"}</button>`;
      else if (isLast) action = `<button class="btn primary" id="msFinish">${run.feedback ? "Ver resultado" : "Entregar prova"}</button>`;
      else action = `<button class="btn primary" id="msNext">Próxima →</button>`;
      const gradeNeeded = run.feedback && checked && q.type === "open" && o.score == null;

      sh.view.innerHTML = `
        <div class="lesson-top">
          <a class="btn ghost" href="#/mestrado" title="Sair (o treino continua salvo)">✕</a>
          <div style="flex:1;min-width:0"><b>${esc(run.title)}</b><br><small class="muted">Questão ${run.i + 1} de ${n} · ${fmt(pts(q))} ponto${pts(q) > 1 ? "s" : ""}</small></div>
          <div class="dt-timer" id="dtTimer"><span id="dtClock"></span><div class="dt-tbar"><i id="dtTbar"></i></div><small id="dtPace"></small></div>
        </div>
        <section class="card slide ms-q">
          <div class="body">
            <div class="kicker">${esc(srcLabel(q))} · Cap. ${q.cap}</div>
            <h2 class="ms-title">${esc(q.title)}</h2>
            ${q.type === "vf" ? `<p class="muted ms-hint">Marque V (verdadeira) ou F (falsa) em cada assertiva.</p>` : q.type === "choice" ? `<p class="muted ms-hint">${isDesign(q) ? "Identifique o desenho de estudo de cada resumo." : "Escolha a alternativa certa para cada item."}</p>` : ""}
            ${contextHtml(q)}
            ${q.type === "open" ? openHtml(q, o, run.feedback && checked, run.feedback)
              : `<ol class="ms-items">${q.items.map((it, k) => itemHtml(q, it, k, run.answers[it.id], run.feedback && checked)).join("")}</ol>`}
            ${run.feedback && checked && q.type !== "open" ? `<div class="why"><b>${fmt(qScore(q, run))} de ${fmt(pts(q))} ponto</b> nesta questão (${q.items.filter((it) => run.answers[it.id] === it.a).length}/${q.items.length} assertivas).</div>` : ""}
          </div>
          <div class="slide-nav">
            ${run.i > 0 ? `<button class="btn" id="msPrev">← Anterior</button>` : ""}
            ${gradeNeeded ? `<button class="btn primary" disabled>Dê uma nota acima para seguir</button>` : action}
          </div>
          ${!run.feedback ? `<div class="dt-grid" aria-label="Ir para questão">${run.qids.map((id, k) => `<button data-go="${k}" class="${k === run.i ? "cur" : ""} ${answeredQ(qById[id]) ? "done" : ""}">${k + 1}</button>`).join("")}</div>
            ${!isLast ? `<div class="row" style="margin-top:10px;justify-content:flex-end"><button class="btn ghost" id="msFinish2">Entregar prova</button></div>` : ""}` : ""}
        </section>`;

      document.querySelectorAll("[data-it]").forEach((b) => b.addEventListener("click", () => {
        const it = itemById[b.dataset.it], qq = itemQ[it.id];
        if (run.checked[qq.id]) return;
        const v = qq.type === "choice" ? +b.dataset.v : b.dataset.v;
        run.answers[it.id] = run.answers[it.id] === v ? undefined : v; // tap again to clear
        if (run.answers[it.id] === undefined) delete run.answers[it.id];
        saveRun();
        const y = window.scrollY; render(); window.scrollTo({ top: y });
      }));
      const ta = document.getElementById("msText");
      if (ta) ta.addEventListener("input", () => { o.text = ta.value; saveRun(); });
      document.querySelectorAll("[data-score]").forEach((b) => b.addEventListener("click", () => {
        o.score = +b.dataset.score; recordOpen(q.id, o.score); sh.save(); saveRun();
        const y = window.scrollY; render(); window.scrollTo({ top: y });
      }));
      const on = (id, fn) => { const el = document.getElementById(id); if (el) el.addEventListener("click", fn); };
      on("msPrev", () => go(run.i - 1));
      on("msNext", () => go(run.i + 1));
      on("msCheck", check);
      on("msFinish", submit);
      on("msFinish2", submit);
      document.querySelectorAll("[data-go]").forEach((b) => b.addEventListener("click", () => go(+b.dataset.go)));
      wirePdfButtons(sh.view);
      tick = setInterval(clock, 500);
      clock();
    }
    function clock() {
      if (!document.getElementById("dtClock")) { clearInterval(tick); return; }
      const el = (Date.now() - run.start) / 1000;
      const frac = el / run.limit;
      document.getElementById("dtClock").textContent = `${mmss(el)} / ${mmss(run.limit)}`;
      document.getElementById("dtTbar").style.width = `${Math.min(100, frac * 100)}%`;
      document.getElementById("dtTimer").className = `dt-timer ${frac > 1 ? "over" : frac > 0.8 ? "warn" : ""}`;
      // pace: the exam's clock after the questions you've finished (answered or corrected)
      const done = run.qids.filter((id) => run.checked[id] || answeredQ(qById[id])).reduce((s, id) => s + pts(qById[id]), 0);
      const diff = done * PER_POINT - el;
      document.getElementById("dtPace").textContent = done ? (diff >= 0 ? `${mmss(diff)} adiantado` : `${mmss(-diff)} atrasado`) : `prova: ${mmss(PER_POINT)}/questão`;
    }
    function check() {
      const q = qById[run.qids[run.i]];
      if (q.type !== "open") q.items.forEach((it) => { if (run.answers[it.id] != null) record(it.id, run.answers[it.id] === it.a); });
      run.checked[q.id] = true;
      sh.save(); saveRun(); render();
    }
    function go(i) { if (i < 0 || i >= n) return; run.i = i; saveRun(); render(); window.scrollTo({ top: 0 }); }
    function submit() {
      const blank = run.qids.filter((id) => !answeredQ(qById[id]) && !run.checked[id]).length;
      if (blank && !confirm(`${blank} questão(ões) ainda têm assertivas em branco. Entregar mesmo assim? (Em branco conta como erro.)`)) return;
      clearInterval(tick);
      finishRun(run);
    }
    sh.setKeyHandler((e) => {
      if (/INPUT|SELECT|TEXTAREA/.test((document.activeElement || {}).tagName || "")) return;
      if (e.key === "ArrowRight") { const b = document.getElementById("msNext"); if (b) b.click(); }
      else if (e.key === "ArrowLeft") go(run.i - 1);
    });
    render();
  }

  function result() {
    sh.setNav("ms-home");
    const r = load(LAST_KEY);
    if (!r) { location.replace("#/mestrado"); return; }
    const qs = r.qids.map((id) => qById[id]).filter(Boolean);
    const runLike = { answers: r.answers, open: r.open || {} };
    const score = qs.reduce((s, q) => s + qScore(q, runLike), 0);
    const p = pct(score, r.max);
    const full = r.mode === "sim" || r.mode.startsWith("prova");
    const inTime = r.secs <= r.limit;
    const pendingOpen = qs.filter((q) => q.type === "open" && (runLike.open[q.id] || {}).score == null);
    const wrongQs = qs.filter((q) => q.type !== "open" && q.items.some((it) => r.answers[it.id] !== it.a));
    const byCap = {};
    qs.filter((q) => q.type !== "open").forEach((q) => q.items.forEach((it) => {
      const c = q.cap; byCap[c] = byCap[c] || { n: 0, ok: 0 }; byCap[c].n++; if (r.answers[it.id] === it.a) byCap[c].ok++;
    }));
    sh.view.innerHTML = `
      <div class="stack">
        <section class="card done-hero">
          <div class="big">${p >= 70 ? "🎉" : "📚"}</div>
          <h1 style="margin-bottom:4px">${fmt(score)} / ${fmt(r.max)}</h1>
          <p style="margin:0"><span class="pill ${p >= 70 ? "good" : "warn"}">${p}% dos pontos</span>${pendingOpen.length ? ` <span class="pill">questão aberta sem nota</span>` : ""}</p>
          <p class="muted" style="margin:8px 0 0">${esc(r.title)}</p>
        </section>
        <section class="card dt-time ${inTime ? "good" : "bad"}">
          <h3 style="margin:0 0 6px">${inTime ? "⏱ Dentro do tempo da prova" : "⏱ Acima do tempo da prova"}</h3>
          <p style="margin:0">Você levou <b>${mmss(r.secs)}</b> ${full ? `de ${mmss(r.limit)}` : `para ${fmt(r.max)} ponto(s) de questões. Na prova de 3 h isso equivale a <b>${mmss(r.limit)}</b>`}.</p>
          <p class="muted" style="margin:6px 0 0">Ritmo: <b>${mmss(r.secs / r.max)}</b> por ponto (prova: ${mmss(PER_POINT)}). Nesse ritmo a prova inteira levaria <b>${mmss((r.secs / r.max) * EXAM_POINTS)}</b>${inTime ? `, ${mmss(EXAM_MIN * 60 - (r.secs / r.max) * EXAM_POINTS)} antes do fim.` : `, ${mmss((r.secs / r.max) * EXAM_POINTS - EXAM_MIN * 60)} a mais que as 3 h.`}</p>
        </section>
        ${pendingOpen.map((q) => `<section class="card ms-pending" data-q="${q.id}"><div class="kicker">${esc(srcLabel(q))} · questão aberta</div><h3>${esc(q.title)}</h3>
          ${(q.ctx || []).map((x) => `<p class="ms-ctx">${esc(x)}</p>`).join("")}
          ${openHtml(q, runLike.open[q.id] || {}, true, true)}</section>`).join("")}
        ${Object.keys(byCap).length ? `<section class="card"><h3 style="margin:0 0 10px">Por capítulo</h3><div class="ms-caps">${Object.entries(byCap).map(([c, x]) => `<div><span>${esc(capName(+c))}</span><span class="bar"><i style="width:${pct(x.ok, x.n)}%;background:${pct(x.ok, x.n) >= 70 ? "var(--good)" : "var(--warn)"}"></i></span><b>${x.ok}/${x.n}</b></div>`).join("")}</div></section>` : ""}
        <div class="row">
          ${wrongQs.length ? `<button class="btn primary" id="msRetry">Refazer as ${wrongQs.length} questões com erros</button>` : ""}
          <a class="btn" href="#/mestrado">Início</a>
        </div>
        <section class="card"><h3 style="margin:0 0 10px">Correção</h3>${qs.map((q, k) => `
          <details class="ms-rev" ${q.type !== "open" && q.items.some((it) => r.answers[it.id] !== it.a) ? "open" : ""}>
            <summary><b>${k + 1}. ${esc(q.title)}</b> <span class="muted">· ${esc(srcLabel(q))}</span> <span class="pill ${qScore(q, runLike) >= pts(q) * 0.7 ? "good" : "warn"}">${fmt(qScore(q, runLike))}/${fmt(pts(q))}</span></summary>
            ${contextHtml(q)}
            ${q.type === "open" ? openHtml(q, runLike.open[q.id] || {}, true, false) : `<ol class="ms-items">${q.items.map((it, j) => itemHtml(q, it, j, r.answers[it.id], true)).join("")}</ol>`}
          </details>`).join("")}</section>
      </div>`;
    wirePdfButtons(sh.view);
    document.querySelectorAll(".ms-pending").forEach((card) => {
      const qid = card.dataset.q;
      const ta = card.querySelector("textarea");
      if (ta) ta.addEventListener("input", () => { r.open[qid] = { ...(r.open[qid] || {}), text: ta.value }; store(LAST_KEY, r); });
      card.querySelectorAll("[data-score]").forEach((b) => b.addEventListener("click", () => {
        r.open = r.open || {};
        r.open[qid] = { ...(r.open[qid] || {}), score: +b.dataset.score };
        recordOpen(qid, +b.dataset.score);
        const newScore = qs.reduce((s, q) => s + qScore(q, { answers: r.answers, open: r.open }), 0);
        r.score = Math.round(newScore * 100) / 100;
        const sess = st().sessions.find((x) => x.id === r.id);
        if (sess) { sess.score = r.score; sess.upd = Date.now(); }
        sh.save(); store(LAST_KEY, r); result();
      }));
    });
    const retry = document.getElementById("msRetry");
    if (retry) retry.addEventListener("click", () => startRun({ qids: shuffle(wrongQs.map((q) => q.id)), title: "Revisão das questões com erros", mode: "bite", feedback: true }));
  }

  function erros() {
    sh.setNav("ms-erros");
    const its = wrongItems().sort((a, b) => (st().q[b.id].w - st().q[a.id].w));
    const qids = [...new Set(its.map((it) => itemQ[it.id].id))];
    sh.view.innerHTML = `<h1>Assertivas que você errou</h1>
      <p class="muted">A última resposta que você deu a estas assertivas estava errada. Acertando no treino, elas saem desta lista.</p>
      ${its.length ? `<div class="row" style="margin-bottom:14px"><button class="btn primary" id="msTrain">Treinar ${Math.min(qids.length, 5)} questão(ões) com erros</button></div>
        <ol class="dt-review">${its.map((it) => { const q = itemQ[it.id], rr = st().q[it.id]; return `<li class="bad"><small class="muted">${esc(srcLabel(q))} · ${esc(q.title)} · errou ${rr.w}×, acertou ${rr.r}×</small>
          <p>${esc(q.type === "choice" && it.t.length > 300 ? it.t.slice(0, 300) + "…" : it.t)}</p>
          <p class="dt-ans good">Gabarito: ${esc(ansLabel(q, it))}</p><p class="ms-exp">${esc(it.e)}</p>${refsHtml(it.refs)}</li>`; }).join("")}</ol>`
        : `<div class="card done-hero"><div class="big">🎯</div><h2>Nenhuma assertiva errada pendente</h2><p class="muted">Faça um treino para descobrir seus pontos fracos.</p><a class="btn primary" href="#/mestrado">Treinar</a></div>`}`;
    wirePdfButtons(sh.view);
    const b = document.getElementById("msTrain");
    if (b) b.addEventListener("click", () => startRun({ qids: shuffle(qids).slice(0, 5), title: "Treino: assertivas erradas", mode: "bite", feedback: true }));
  }

  function banco(qs) {
    sh.setNav("ms-banco");
    let cap = "", onlyExam = false;
    sh.view.innerHTML = `<h1>Banco de questões</h1>
      <p class="muted">${ITEMS.length} assertivas em ${QS.length} questões. O gabarito aparece em verde, com a explicação e a página do livro. Gabarito das provas: não oficial.</p>
      <div class="search-box"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="11" cy="11" r="7"/><path d="M20 20l-3.5-3.5"/></svg>
        <input id="msQ" type="search" placeholder="Buscar: “letalidade”, “pessoa-tempo”, “Swaroop”…" autocomplete="off" aria-label="Buscar assertivas" value="${esc(qs || "")}"></div>
      <div class="chips" style="margin:12px 0"><button class="chip on" data-c="">Todos</button>${CAP_NUMS.map((c) => `<button class="chip" data-c="${c}">Cap. ${c}</button>`).join("")}<button class="chip" data-exam="1">📝 Só provas</button></div>
      <p class="muted" id="msCount" style="margin:0 0 8px"></p><ol class="dt-review" id="msList"></ol>`;
    const norm = (s) => s.normalize("NFD").replace(/[̀-ͯ]/g, "").toLowerCase();
    const list = document.getElementById("msList"), input = document.getElementById("msQ");
    function draw() {
      const terms = norm(input.value).split(/\s+/).filter(Boolean);
      const rows = ITEMS.filter((it) => { const q = itemQ[it.id]; return (!cap || q.cap === +cap) && (!onlyExam || q.prova)
        && terms.every((t) => norm(`${q.title} ${(q.ctx || []).join(" ")} ${it.t} ${it.e}`).includes(t)); });
      document.getElementById("msCount").textContent = `${rows.length} assertiva(s)`;
      list.innerHTML = rows.slice(0, 200).map((it) => {
        const q = itemQ[it.id], rr = st().q[it.id];
        return `<li><small class="muted">${esc(srcLabel(q))} · ${esc(q.title)}${rr ? ` · você: ✓${rr.r} ✗${rr.w}` : ""}</small>
          <p>${esc(q.type === "choice" && it.t.length > 300 ? it.t.slice(0, 300) + "…" : it.t)}</p>
          <p class="dt-ans good">Gabarito: ${esc(ansLabel(q, it))}${it.disc ? " (discutível)" : ""}</p><p class="ms-exp">${esc(it.e)}</p>${refsHtml(it.refs)}</li>`;
      }).join("") + (rows.length > 200 ? `<li class="muted">… refine a busca para ver mais</li>` : "");
      wirePdfButtons(list);
      history.replaceState(null, "", input.value.trim() ? `#/mestrado/banco/${encodeURIComponent(input.value.trim())}` : "#/mestrado/banco");
    }
    input.addEventListener("input", draw);
    document.querySelectorAll(".chips .chip").forEach((c) => c.addEventListener("click", () => {
      if (c.dataset.exam) { onlyExam = !onlyExam; c.classList.toggle("on", onlyExam); }
      else { cap = c.dataset.c; document.querySelectorAll(".chips [data-c]").forEach((x) => x.classList.toggle("on", x === c)); }
      draw();
    }));
    draw();
  }

  /* ---------------- the book: chapter summaries and local PDFs ---------------- */
  function livro(capArg, secArg) {
    sh.setNav("ms-livro");
    if (capArg) return capitulo(+capArg, secArg);
    const missing = [...new Set(DATA.pdfs.map((p) => p.key))].filter((k) => !pdfKeys.has(k));
    sh.view.innerHTML = `<h1>Livro-texto</h1>
      <p class="muted">Medronho RA, Bloch KV, Luiz RR, Werneck GL (eds.). <i>Epidemiologia</i>. 2ª ed. São Paulo: Atheneu. Resumos escritos para este app; leia o capítulo no livro para os detalhes.</p>
      <div class="stack">
        ${CAP_NUMS.map((c) => { const x = chapterStats(c), cp = CAPS[c]; return `<a class="card ms-cap" href="#/mestrado/livro/${c}">
          <span class="ms-capn">${c}</span><span class="t"><b>${esc(cp.title)}</b><small class="muted">${esc(cp.authors)} · p. ${cp.from}-${cp.to}</small>
          <span class="bar"><i style="width:${pct(x.seen, x.n)}%;background:var(--accent)"></i></span><small class="muted">${x.seen}/${x.n} assertivas vistas${x.seen ? ` · ${pct(x.right, x.seen)}% de acerto` : ""}</small></span></a>`; }).join("")}
        <section class="card">
          <h3 style="margin:0 0 6px">📄 Abrir o PDF na página certa</h3>
          <p class="muted" style="margin:0 0 10px;font-size:.93rem">Se você tem os PDFs dos capítulos, carregue-os aqui. Eles ficam guardados <b>só neste navegador</b> (não vão para a nuvem nem para o site), e cada referência ganha um botão “PDF ↗” que abre a página citada.</p>
          <p style="margin:0 0 10px;font-size:.93rem">${pdfKeys.size ? `✅ Carregados: ${[...pdfKeys].sort().join(", ")}` : "Nenhum PDF carregado neste aparelho."}${missing.length && pdfKeys.size ? `<br><span class="muted">Faltam: ${missing.join(", ")}</span>` : ""}</p>
          <div class="row"><label class="btn primary" for="msPdfIn">Escolher PDFs…</label><input id="msPdfIn" type="file" accept="application/pdf,.pdf" multiple hidden>
            ${pdfKeys.size ? `<button class="btn ghost" id="msPdfClear">Remover deste aparelho</button>` : ""}</div>
          <p class="muted" style="margin:10px 0 0;font-size:.85rem">Os nomes dos arquivos precisam conter o capítulo, como “Medronho_Cap2.pdf”, “Cap3_Pt1”, “Cap3_Pt2” e “Cap8e18”.</p>
        </section>
      </div>`;
    document.getElementById("msPdfIn").addEventListener("change", async (e) => {
      const files = [...e.target.files];
      let ok = 0; const skipped = [];
      for (const f of files) {
        const key = pdfKeyFromName(f.name);
        if (!key || !DATA.pdfs.some((p) => p.key === key)) { skipped.push(f.name); continue; }
        try { const buf = await f.arrayBuffer(); await pdfOp("readwrite", (s) => s.put(buf, key)); ok++; } catch { skipped.push(f.name); }
      }
      await refreshPdfKeys();
      sh.toast(`${ok} PDF(s) guardado(s)${skipped.length ? ` · ignorados: ${skipped.join(", ")}` : ""}`);
      livro();
    });
    const clr = document.getElementById("msPdfClear");
    if (clr) clr.addEventListener("click", async () => { if (!confirm("Remover os PDFs guardados neste navegador?")) return; await pdfOp("readwrite", (s) => s.clear()); await refreshPdfKeys(); livro(); });
  }
  function capitulo(c, secArg) {
    const cp = CAPS[c];
    if (!cp) { location.replace("#/mestrado/livro"); return; }
    const secs = DATA.sections.filter((s) => s.cap === c);
    const qsFor = (sid) => QS.filter((q) => (q.items || []).some((it) => it.refs[0] && it.refs[0].s === sid) || (q.refs && q.refs.some((r) => r.s === sid)));
    const prev = CAP_NUMS[CAP_NUMS.indexOf(c) - 1], next = CAP_NUMS[CAP_NUMS.indexOf(c) + 1];
    sh.view.innerHTML = `<div class="lesson-top"><a class="btn ghost" href="#/mestrado/livro" title="Todos os capítulos">←</a><div style="flex:1;min-width:0"><small class="muted">Capítulo ${c} · p. ${cp.from}-${cp.to}</small><br><b>${esc(cp.title)}</b></div></div>
      <p class="muted" style="margin-top:0">${esc(cp.authors)}</p>
      <div class="stack">${secs.map((s) => {
        const qq = qsFor(s.id), p = pdfFor(s.from);
        return `<section class="card ms-sec ${secArg === s.id ? "hl" : ""}" id="${s.id}">
          <div class="row" style="justify-content:space-between;align-items:baseline"><h3 style="margin:0">${esc(s.title)}</h3><small class="muted">p. ${s.from}-${s.to}</small></div>
          <ul>${s.pts.map((x) => `<li>${esc(x)}</li>`).join("")}</ul>
          <div class="row">${qq.length ? `<button class="btn" data-train="${s.id}">Treinar ${qq.length} questão(ões) deste trecho</button>` : ""}
            ${p && pdfKeys.has(p.key) ? `<button class="btn ghost" data-pdf="${s.from}">Abrir PDF p. ${s.from} ↗</button>` : ""}</div>
        </section>`;
      }).join("")}</div>
      <div class="row" style="margin-top:16px;justify-content:space-between">${prev ? `<a class="btn" href="#/mestrado/livro/${prev}">← Cap. ${prev}</a>` : "<span></span>"}${next ? `<a class="btn" href="#/mestrado/livro/${next}">Cap. ${next} →</a>` : ""}</div>`;
    wirePdfButtons(sh.view);
    document.querySelectorAll("[data-train]").forEach((b) => b.addEventListener("click", () => {
      const s = secById[b.dataset.train];
      startRun({ qids: weightedPick(qsFor(s.id), 3), title: `Treino: ${s.title}`, mode: "bite", feedback: true });
    }));
    if (secArg) { const el = document.getElementById(secArg); if (el) setTimeout(() => el.scrollIntoView({ behavior: "smooth", block: "start" }), 30); }
  }

  let pdfReady = null;
  window.Mestrado = {
    route(parts, shell) {
      sh = shell;
      clearInterval(tick);
      if (!pdfReady) pdfReady = refreshPdfKeys();
      const go = () => {
        const [a, ...rest] = parts;
        if (a === "quiz") quiz();
        else if (a === "resultado") result();
        else if (a === "erros") erros();
        else if (a === "livro") livro(rest[0], rest[1]);
        else if (a === "banco") banco(rest.length ? decodeURIComponent(rest.join("/")) : "");
        else home();
      };
      // the PDF list comes from IndexedDB; wait for it once so references know whether to offer "PDF ↗"
      if (pdfKeys.size || pdfReady === true) go(); else pdfReady.then(() => { pdfReady = true; go(); });
    },
  };
})();
